// Normalize the Gmail payload into the simple { from, subject, body, threadId }
// shape that Denizen's /api/email-inbound expects.
const payload = $input.item.json || {};
const headers = payload.payload?.headers || [];
function h(name) {
  const f = headers.find(x => (x.name || '').toLowerCase() === name.toLowerCase());
  return f ? String(f.value || '') : '';
}
// Body may be inline or in parts; pick the first text/plain we can find.
function extractBody(part) {
  if (!part) return '';
  if (part.mimeType === 'text/plain' && part.body?.data) {
    return Buffer.from(part.body.data, 'base64').toString('utf8');
  }
  if (Array.isArray(part.parts)) {
    for (const p of part.parts) {
      const t = extractBody(p);
      if (t) return t;
    }
  }
  return '';
}
const body = extractBody(payload.payload) || payload.snippet || '';
return [{
  json: {
    from: h('from'),
    subject: h('subject'),
    body,
    threadId: payload.threadId || null
  }
}];
